        assert.equal(guard().isIgnoredPath('.github/workflows/x.yml', IGNORED), true);
        assert.equal(guard().isIgnoredPath('docs/readme.md', IGNORED), true);
        assert.equal(guard().isIgnoredPath('site/index.html', IGNORED), true);
