function workflowRunBlock(wf) {
    var start = wf.indexOf('workflow_run:');
    if (start === -1) return '';
    var rest = wf.slice(start + 'workflow_run:'.length);
    var end = rest.search(/\n  (push|workflow_dispatch|schedule):/);
    return end === -1 ? rest : rest.slice(0, end);
}

